if (runState.Players.All((Player p) => p.Gold >= 100))
		{
			return runState.CurrentActIndex > 0;
		}
		return false;

if (runState.Players.Count == 1)
		{
			return true;
		}
		foreach (Player player in runState.Players)
		{
			if ((decimal)player.Creature.CurrentHp <= base.DynamicVars.HpLoss.BaseValue)
			{
				return false;
			}
		}
		return true;

if (runState.CurrentActIndex < 1)
		{
			return false;
		}
		if (runState.Players.Count > 1)
		{
			return false;
		}
		return runState.Players.All((Player player) => player.Gold >= 100 || player.Potions.Any((PotionModel potion) => potion is FoulPotion));

if (runState.Players.Count == 1)
		{
			return true;
		}
		foreach (Player player in runState.Players)
		{
			if ((decimal)player.Creature.CurrentHp <= base.DynamicVars["SoloHp"].BaseValue)
			{
				return false;
			}
		}
		return true;

if (runState.CurrentActIndex == 0)
		{
			return false;
		}
		if (runState.Players.Any((Player p) => !GetValidRelics(p).Any()))
		{
			return false;
		}
		if (runState.Players.Any((Player p) => p.Gold < 100))
		{
			return false;
		}
		if (runState.Players.Any((Player p) => !p.Potions.Any()))
		{
			return false;
		}
		return true;

if (runState.CurrentActIndex == 0)
		{
			return false;
		}
		return runState.Players.All((Player p) => GetValidRelics(p).Count() >= 5);

if (runState.TotalFloor > 6)
		{
			return runState.Players.All((Player p) => p.Deck.Cards.Any((CardModel c) => c.IsRemovable));
		}
		return false;

if (runState.CurrentActIndex == 1)
		{
			return runState.Players.All((Player player) => player.Potions.Any());
		}
		return false;

if (runState.CurrentActIndex < 2)
		{
			return runState.Players.All((Player p) => p.Gold >= 150);
		}
		return false;

if (runState.CurrentActIndex == 0 && runState.Players.All((Player p) => p.Deck.Cards.Count > 0))
		{
			return runState.Players.All((Player p) => p.Creature.CurrentHp >= 10);
		}
		return false;

if (runState.CurrentActIndex == 1)
		{
			return runState.Players.All((Player p) => p.Gold >= 100);
		}
		return false;
